const listFleetCohorts = `-- name: ListFleetCohorts :many
SELECT c.org_id, c.id, c.name, c.description, c.rule, c.owner_user_id, c.baseline, c.created_by, c.created_at, c.updated_at, (SELECT count(*) FROM pc.fleet_cohort_members m WHERE m.org_id = c.org_id AND m.cohort_id = c.id)::integer AS static_members
FROM pc.fleet_cohorts c
WHERE c.org_id = $1 AND ($2::text IS NULL OR c.name > $2::text)
ORDER BY c.name
LIMIT $3
`

type ListFleetCohortsRow struct {
	OrgID         ids.OrgID
	ID            ids.UUID
	Name          string
	Description   string
	Rule          []byte
	OwnerUserID   ids.UUID
	Baseline      []byte
	CreatedBy     string
	CreatedAt     time.Time
	UpdatedAt     time.Time
	StaticMembers int32
}

func (q *Queries) ListFleetCohorts(ctx context.Context, orgID ids.OrgID, after *string, maxRows int32) ([]ListFleetCohortsRow, error) {
	rows, err := q.db.Query(ctx, listFleetCohorts, orgID, after, maxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListFleetCohortsRow{}
	for rows.Next() {
		var i ListFleetCohortsRow
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.Name,
			&i.Description,
			&i.Rule,
			&i.OwnerUserID,
			&i.Baseline,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StaticMembers,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

